return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'fi','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:13+00:00','po-revision-date'=>'2026-10-31T05:53:13+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Täydentää puuttuvat käännökset sivustollesi jo asennetuille lisäosille ja teemoille.','Translations'=>'Käännökset','Babilim Settings'=>'Babilim Asetukset','Settings'=>'Asetukset','You are not allowed to do this.'=>'Sinulla ei ole oikeutta tähän toimintoon.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Valitse vähemmän komponentteja: enintään %1$d toimintoa per ajo (valitsit %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Tätä komponenttia ei ole asennettu tälle sivustolle, joten sille ei voi pyytää käännöstä.','Already installed.'=>'Asennettu jo.','Downloaded and installed.'=>'Ladattu ja asennettu.','Babilim has not been enabled for this site yet.'=>'Babilimia ei ole vielä otettu käyttöön tällä sivustolla.','No build is available to download for this locale.'=>'Tälle kielelle ei ole ladattavaa versiota.','Rolled back to the previous build.'=>'Palautettu edelliseen versioon.','Rolled back and reported.'=>'Palautettu ja ilmoitettu.','Rolled back, but the report could not be sent: %s'=>'Palautettu, mutta ilmoitusta ei voitu lähettää: %s','Removed.'=>'Poistettu.','Translation requested.'=>'Käännöstä pyydetty.','This component was already uploaded. Babilim is checking it now.'=>'Tämä komponentti on jo lähetetty. Babilim tarkistaa sitä parhaillaan.','Upload cancelled.'=>'Siirto peruttu.','Upload complete — translation requested.'=>'Siirto valmis – käännöstä pyydetty.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Tämä komponentti ei ilmoita versionumeroa, joten sil